<?php
$page_title = 'Template Manager'; require __DIR__ . '/includes/header.php'; require __DIR__ . '/includes/sidebar.php';
$templates=[]; try {$templates=db()->query('SELECT t.*, c.name AS category_name FROM templates t LEFT JOIN template_categories c ON c.id=t.category_id ORDER BY t.sort_order,t.id')->fetchAll();} catch(Throwable) {}
?><header class="admin-header"><span class="eyebrow">CATALOG</span><h1>Template manager</h1><p class="muted">Template JSON tetap hidup di foldernya; database mengatur harga, status, dan urutan.</p></header><section class="table-wrap"><table><thead><tr><th>Nama</th><th>Kategori</th><th>Harga</th><th>Status</th><th>Urutan</th></tr></thead><tbody><?php foreach($templates as $item): ?><tr><td><strong><?= e($item['name']) ?></strong><br><small><?= e($item['slug']) ?></small></td><td><?= e($item['category_name'] ?? '-') ?></td><td><?= e(money((int)$item['price'])) ?></td><td><span class="status-badge"><?= e($item['status']) ?></span></td><td><?= e((string)$item['sort_order']) ?></td></tr><?php endforeach; ?><?php if(!$templates): ?><tr><td colspan="5">Belum ada template di database. Sinkronkan data template JSON terlebih dahulu.</td></tr><?php endif; ?></tbody></table></section><?php require __DIR__ . '/includes/footer.php'; ?>
